#[path="../owner_registry.rs"]mod owner_registry;
#[path="../owner_budget.rs"]mod owner_budget;
#[path="../journal.rs"]mod journal;
#[path="../owner.rs"]mod owner;
use std::alloc::{GlobalAlloc,Layout,System};use std::sync::atomic::{AtomicUsize,Ordering};use glam::DVec3;use ingetrazo_core::mesh::{Mesh,MeshVertex};
static CALLS:AtomicUsize=AtomicUsize::new(0);static MAX:AtomicUsize=AtomicUsize::new(0);static BYTES:AtomicUsize=AtomicUsize::new(0);
struct Count;unsafe impl GlobalAlloc for Count{unsafe fn alloc(&self,l:Layout)->*mut u8{CALLS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(l.size(),Ordering::Relaxed);MAX.fetch_max(l.size(),Ordering::Relaxed);System.alloc(l)}unsafe fn dealloc(&self,p:*mut u8,l:Layout){System.dealloc(p,l)}unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{CALLS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(n,Ordering::Relaxed);MAX.fetch_max(n,Ordering::Relaxed);System.realloc(p,l,n)}}#[global_allocator]static ALLOC:Count=Count;
fn main(){let mut rows=vec![];for n in [1000usize,50000]{let mut m=Mesh::new();m.vertices.reserve_exact(n+128);m.edges.reserve_exact(128);for i in 0..n{m.vertices.push(MeshVertex::new(DVec3::new(i as f64,0.,0.)));}m.vertices[0].edges.reserve_exact(128);let mut o=owner::JournalOwner::new(m).unwrap();BYTES.store(0,Ordering::Relaxed);let mut prime=o.try_begin().unwrap();prime.add_edge(DVec3::ZERO,DVec3::new(99999.,1.,0.)).unwrap();o.commit(prime).unwrap();o.undo().unwrap();let capacity_growth_bytes=BYTES.load(Ordering::Relaxed);CALLS.store(0,Ordering::Relaxed);BYTES.store(0,Ordering::Relaxed);MAX.store(0,Ordering::Relaxed);for i in 0..64{let mut t=o.try_begin().unwrap();t.add_edge(DVec3::ZERO,DVec3::new(100000.+i as f64,1.,0.)).unwrap();o.commit(t).unwrap();}for _ in 0..64{o.undo().unwrap();}for _ in 0..64{o.redo().unwrap();}let calls=CALLS.load(Ordering::Relaxed);let bytes=BYTES.load(Ordering::Relaxed);let max=MAX.load(Ordering::Relaxed);assert!(max<16384);assert_eq!(o.mesh().vertices.len(),n+64);rows.push(serde_json::json!({"base_vertices":n,"initial_capacity_growth_bytes":capacity_growth_bytes,"append_undo_redo":64,"allocation_calls":calls,"allocated_bytes":bytes,"largest_allocation":max,"cold_vertex_rows":o.registry_metrics().cold_vertex_rows,"publication_rows":o.registry_metrics().publication_rows}));}println!("{}",serde_json::to_string_pretty(&rows).unwrap());}